from solution import min_product_tuple


def test_issue_example_from_issue():
    """Example from issue: minimum product from pairs of tuples is 8."""
    assert min_product_tuple([(2, 7), (2, 6), (1, 8), (4, 9)]) == 8  # 2*7=14, 2*6=12, 1*8=8, 4*9=36, min=8


def test_issue_single_pair():
    """Single pair: minimum product from pairs of tuples is its product."""
    assert min_product_tuple([(3, 5)]) == 15  # 3*5=15, min=15


def test_issue_minimum_first():
    """Minimum product from pairs of tuples when minimum is first."""
    assert min_product_tuple([(1, 2), (5, 6), (3, 4)]) == 2  # 1*2=2, 5*6=30, 3*4=12, min=2


def test_issue_minimum_last():
    """Minimum product from pairs of tuples when minimum is last."""
    assert min_product_tuple([(5, 6), (3, 4), (1, 2)]) == 2  # 5*6=30, 3*4=12, 1*2=2, min=2


def test_issue_zero_minimum():
    """Minimum product from pairs of tuples with zero product present."""
    assert min_product_tuple([(5, 6), (0, 9), (3, 4)]) == 0  # 5*6=30, 0*9=0, 3*4=12, min=0


def test_issue_negative_minimum():
    """Minimum product from pairs of tuples with negative product present."""
    assert min_product_tuple([(2, 3), (-2, 3), (4, 5)]) == -6  # 2*3=6, -2*3=-6, 4*5=20, min=-6


def test_issue_tie_for_minimum():
    """Minimum product from pairs of tuples when all products tie."""
    assert min_product_tuple([(2, 3), (3, 2), (1, 6)]) == 6  # 2*3=6, 3*2=6, 1*6=6, min=6


def test_issue_product_not_sum():
    """Minimum product from pairs of tuples means product, not sum."""
    assert min_product_tuple([(5, 5), (2, 9)]) == 18  # 5*5=25, 2*9=18, min=18; sums 10 vs 11 would give 10


def test_contract_minimum_not_maximum():
    """Contract: min_product_tuple(list1) returns minimum product, not maximum."""
    assert min_product_tuple([(7, 8), (2, 3), (4, 5)]) == 6  # 7*8=56, 2*3=6, 4*5=20, min=6, max=56


def test_contract_product_value():
    """Contract: min_product_tuple(list1) returns product value, not sum."""
    assert min_product_tuple([(10, 2), (3, 3)]) == 9  # 10*2=20, 3*3=9, min=9; sums 12 vs 6 would give 6
